// Load Payload
// Logic below uses the shared library (OF.*) bundled at the end of this node.
const OF = __lib();
return [{ json: { db: { rfq_id: $input.first().json.rfq_id } } }];

function __lib() { return {}; }

// Build Quote + OpenAI Request
// Logic below uses the shared library (OF.*) bundled at the end of this node.
const OF = __lib();
const SYSTEM_PROMPT = "You format flight quotes for Offshore Fares, a B2B fares desk serving travel agents. You receive QUOTE_DATA produced by our fare desk. Write a clear, professional quote for the agent.\n\nNON-NEGOTIABLE RULES:\n1. Copy every commercial value VERBATIM from QUOTE_DATA: airline, route_label/route_codes, departure/return labels, cabin_label, fare_label, fare_amount_label, total_label, baggage, change_penalty, refund_penalty, validity_label. Never round, convert, recalculate, abbreviate or reformat numbers, currencies or dates.\n2. Never add information that is not in QUOTE_DATA (no extra fares, discounts, availability claims, flight numbers, times, baggage or rule details). Do not write any number that is not in QUOTE_DATA.\n3. Never say the booking is confirmed, guaranteed or ticketed. Include this sentence exactly in both texts: \"Fares and availability remain subject to confirmation until ticketed.\"\n4. Keep the option numbering of QUOTE_DATA (Option 1, Option 2, ...).\n\nEMAIL (email_subject + email_body):\n- email_subject must contain the rfq_number, e.g. \"<rfq_number> | Business Class options BOM → LHR (17 Nov 2026 – 25 Nov 2026)\".\n- Greeting with greeting_name if present (\"Dear John,\"), one short thank-you line, then for each option a block with the labels: Route, Departure, Return (if any), Cabin, Fare (fare_label and total_label), Baggage, Change penalty, Refund penalty, Fare validity (\"until \" + validity_label).\n- Departure and Return lines must contain departure_date_label / return_date_label exactly.\n- End with: \"Please let us know which option you would like to proceed with.\", the disclaimer sentence, then \"Kind regards,\" and \"Offshore Fares\".\n- If preferred_airlines is not empty you may mention which option matches the preference (without inventing anything).\n\nWHATSAPP (whatsapp_body):\n- Compact (max ~900 characters), plain text, *bold* option titles allowed, no greetings longer than one line.\n- Per option: airline, route_codes, stops_label, departure_label (and return_label), fare_label, baggage, change and refund penalty.\n- End with the validity, \"Reply with the option number to proceed.\" and the disclaimer sentence.";

const cfg = OF.config.getConfig($env);
const ctx = $input.first().json.r;
const now = new Date();
const check = OF.fares.validateFareOptions(ctx.options, { rfq: { trip_type: ctx.trip_type, cabin: ctx.cabin }, now });
if (!check.ok) throw new Error(`Fare options are not quotable: ${check.errors.join('; ')}`);
const options = check.options.map((o, i) => Object.assign(o, { option_code: ctx.options[i].option_code }));
const model = OF.quote.buildQuoteModel({ rfq: ctx, requirements: ctx.requirements, contact: ctx.contact, options, timeZone: cfg.BUSINESS_TIMEZONE, now });
const email = OF.quote.renderEmail(model, cfg.COMPANY_SIGNATURE);
const whatsapp = OF.quote.renderWhatsApp(model);
const request = OF.openai.buildChatRequest({
  model: cfg.OPENAI_MODEL, system: SYSTEM_PROMPT, user: OF.quote.buildFormatterUserContent(model, ctx.last_inbound_channel || ctx.source_channel),
  schema: OF.quote.QUOTE_SCHEMA, schemaName: 'quote_texts', temperature: cfg.OPENAI_FORMATTER_TEMPERATURE, maxTokens: 2500,
});
return [{ json: {
  ai_mode: cfg.AI_PROVIDER === 'rules' ? 'rules' : 'openai', openai_request: request,
  rfq_id: ctx.id, model, template: { email_subject: email.subject, email_body: email.body, whatsapp_body: whatsapp },
  valid_until: OF.fares.quoteValidUntil(options), require_approval: cfg.REQUIRE_HUMAN_APPROVAL,
} }];

// ======================================================================
// Shared library – GENERATED from lib/ by scripts/build-workflows.js.
// Do not edit here: edit lib/*.js, run `npm test` and `npm run build`.
// ======================================================================
function __lib() {
  const __defs = {
  "lib/quote": function (module, exports, require) {
'use strict';
/**
 * WF10 – Quote model, deterministic templates and AI-output validation.
 *
 * All commercial strings (fares, penalties, baggage, dates, flight numbers) are
 * formatted HERE from structured fare data. The model may only re-phrase the
 * surrounding text; validateFormattedQuote() rejects any output that alters,
 * omits or invents a number, in which case the deterministic template is used.
 */
const { S } = require('./openai');
const { containsSecret } = require('./security');
const { formatMoney, listJoin } = require('./text');
const { formatLong, formatShort, formatDateTime } = require('./dates');
const { cityName } = require('./airports');
const { CABIN_LABEL, paxLabel } = require('./requirements');
const { isExpired } = require('./fares');

const QUOTE_SCHEMA = S.obj({
  email_subject: S.str(),
  email_body: S.str(),
  whatsapp_body: S.str(),
});

const DISCLAIMER = 'Fares and availability remain subject to confirmation until ticketed.';

function formatInZone(iso, timeZone) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  try {
    const parts = Object.fromEntries(new Intl.DateTimeFormat('en-GB', {
      timeZone: timeZone || 'UTC', day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
    }).formatToParts(d).map((p) => [p.type, p.value]));
    return `${parts.day} ${parts.month} ${parts.year}, ${parts.hour}:${parts.minute} ${timeZone || 'UTC'}`;
  } catch (_) {
    return `${d.toISOString().slice(0, 16).replace('T', ' ')} UTC`;
  }
}

function durationLabel(minutes) {
  if (!Number.isInteger(minutes) || minutes <= 0) return null;
  return `${Math.floor(minutes / 60)}h ${String(minutes % 60).padStart(2, '0')}m`;
}

function routeOf(segments, direction) {
  const segs = (segments || []).filter((s) => s.direction === direction);
  if (!segs.length) return null;
  const codes = [segs[0].from].concat(segs.map((s) => s.to));
  return codes;
}

/** Build the canonical quote model from an RFQ, contact and validated fare options. */
function buildQuoteModel({ rfq, requirements, contact, options, timeZone, now }) {
  const req = requirements || {};
  const pax = req.passengers || {};
  const payingPax = (pax.adults || 0) + (pax.children || 0);
  const cabin = CABIN_LABEL[req.cabin] || 'Business';
  const opts = (options || []).map((o, i) => {
    const outCodes = routeOf(o.flight_segments, 'OUTBOUND') || [req.origin && req.origin.iata, req.destination && req.destination.iata].filter(Boolean);
    const inCodes = routeOf(o.flight_segments, 'INBOUND');
    const amount = Number(o.fare.amount);
    const perPax = o.fare_basis !== 'TOTAL';
    const total = perPax && payingPax > 0 ? amount * payingPax : null;
    const outSegs = (o.flight_segments || []).filter((s) => s.direction === 'OUTBOUND');
    const inSegs = (o.flight_segments || []).filter((s) => s.direction === 'INBOUND');
    return {
      no: i + 1,
      option_code: o.option_code || `OPT-${String(i + 1).padStart(3, '0')}`,
      airline: o.airline,
      route_label: outCodes.map((c) => `${cityName(c)} (${c})`).join(' → '),
      route_codes: outCodes.join(' → '),
      return_route_codes: inCodes ? inCodes.join(' → ') : null,
      outbound_flights: outSegs.map((s) => s.flight_no).filter(Boolean).join(' / ') || null,
      return_flights: inSegs.map((s) => s.flight_no).filter(Boolean).join(' / ') || null,
      departure_label: formatDateTime(o.departure_at),
      departure_date_label: formatLong(String(o.departure_at).slice(0, 10)),
      return_label: o.return_departure_at ? formatDateTime(o.return_departure_at) : null,
      return_date_label: o.return_departure_at ? formatLong(String(o.return_departure_at).slice(0, 10)) : null,
      stops_label: o.stops === 0 ? 'Non-stop' : `${o.stops} stop${o.stops > 1 ? 's' : ''}${outCodes.length > 2 ? ` (${outCodes.slice(1, -1).join(', ')})` : ''}`,
      duration_label: durationLabel(o.total_duration_minutes),
      cabin_label: `${CABIN_LABEL[o.cabin] || cabin} Class`,
      fare_amount_label: formatMoney(amount, o.fare.currency),
      fare_label: perPax ? `${formatMoney(amount, o.fare.currency)} per passenger` : `${formatMoney(amount, o.fare.currency)} total`,
      total_label: total ? `${formatMoney(total, o.fare.currency)} total for ${payingPax} passenger${payingPax > 1 ? 's' : ''}` : null,
      baggage: o.baggage,
      change_penalty: o.change_penalty,
      refund_penalty: o.refund_penalty,
      validity_label: formatInZone(o.fare_valid_until, timeZone),
      expired: isExpired(o, now),
    };
  });
  const first = (contact && (contact.first_name || contact.name)) || null;
  return {
    rfq_number: rfq.rfq_number,
    greeting_name: first,
    cabin_label: `${cabin} Class`,
    route_summary: `${req.origin ? req.origin.iata : ''} → ${req.destination ? req.destination.iata : ''}`,
    travel_dates: req.return_date ? `${formatShort(req.departure_date)} – ${formatShort(req.return_date)}` : formatShort(req.departure_date),
    pax_label: paxLabel(req),
    preferred_airlines: req.preferred_airlines || [],
    options: opts,
    disclaimer: DISCLAIMER,
  };
}

function renderEmail(model, signature) {
  const lines = [];
  lines.push(model.greeting_name ? `Dear ${model.greeting_name},` : 'Dear Partner,', '');
  lines.push('Thank you for your request.', '');
  lines.push(`Please find the available ${model.cabin_label} options below for ${model.route_summary} (${model.travel_dates}, ${model.pax_label}).`, '');
  for (const o of model.options) {
    lines.push(`OPTION ${o.no} — ${o.airline}`, '');
    lines.push('Route:', `${o.route_label} (${o.stops_label})`, '');
    lines.push('Departure:', `${o.departure_date_label}${o.outbound_flights ? ` — ${o.outbound_flights}, departs ${o.departure_label}` : ''}`, '');
    if (o.return_date_label) lines.push('Return:', `${o.return_date_label}${o.return_flights ? ` — ${o.return_flights}, departs ${o.return_label}` : ''}`, '');
    lines.push('Cabin:', o.cabin_label, '');
    lines.push('Fare:', o.fare_label + (o.total_label ? ` (${o.total_label})` : ''), '');
    lines.push('Baggage:', o.baggage, '');
    lines.push('Change penalty:', o.change_penalty, '');
    lines.push('Refund penalty:', o.refund_penalty, '');
    lines.push('Fare validity:', `until ${o.validity_label}`, '');
  }
  lines.push('Please let us know which option you would like to proceed with.', '');
  lines.push(model.disclaimer, '');
  lines.push('Kind regards,', signature || 'Offshore Fares');
  const subject = `${model.rfq_number} | ${model.cabin_label} options ${model.route_summary} (${model.travel_dates})`;
  return { subject, body: lines.join('\n') };
}

function renderWhatsApp(model) {
  const lines = [];
  lines.push(`${model.greeting_name ? `Hi ${model.greeting_name}, here` : 'Here'} are the ${model.cabin_label} options for ${model.route_summary} (${model.travel_dates}, ${model.pax_label}) – ref ${model.rfq_number}`);
  for (const o of model.options) {
    lines.push('');
    lines.push(`*Option ${o.no} – ${o.airline}*`);
    lines.push(`${o.route_codes} · ${o.stops_label}`);
    lines.push(`Out ${o.departure_label}${o.return_label ? ` · Ret ${o.return_label}` : ''}`);
    lines.push(`${o.fare_label}${o.total_label ? ` (${o.total_label})` : ''}`);
    lines.push(`Bag ${o.baggage} · Change ${o.change_penalty} · Refund ${o.refund_penalty}`);
  }
  lines.push('');
  const validity = model.options.map((o) => o.validity_label).sort()[0];
  lines.push(`Valid until ${validity}. Reply with the option number to proceed. ${model.disclaimer}`);
  return lines.join('\n');
}

function buildFormatterUserContent(model, channelHint) {
  return [
    `PRIMARY_CHANNEL: ${channelHint || 'email'}`,
    'QUOTE_DATA (trusted, produced by our fare desk – copy every value verbatim):',
    JSON.stringify(model, null, 2),
    'The agent request is summarised in QUOTE_DATA. Do not use any other source.',
  ].join('\n');
}

/** Numeric tokens normalised for comparison ("2,450.00" -> "2450", "02:40" -> "2:40"). */
function numericTokens(text) {
  const out = [];
  const re = /\d[\d,]*(?:\.\d+)?(?::\d{2})?/g;
  let m;
  while ((m = re.exec(String(text || ''))) !== null) {
    let t = m[0].replace(/,(?=\d{3}\b)/g, '').replace(/,$/, '');
    if (t.includes(':')) t = t.split(':').map((p) => String(Number(p))).join(':');
    else if (t.includes('.')) t = String(Number(t));
    else t = String(Number(t));
    out.push(t);
  }
  return out;
}

const FORBIDDEN = /\b(guaranteed|is confirmed|are confirmed|confirmed booking|has been booked|(?:has been|have been|is|are) ticketed|discount(?:ed)?|special price)\b/i;

/**
 * Validate AI-formatted text against the quote model.
 * @returns {{ ok: boolean, errors: string[] }}
 */
function validateFormattedQuote(ai, model) {
  const errors = [];
  const data = ai || {};
  const email = String(data.email_body || '');
  const wa = String(data.whatsapp_body || '');
  const subject = String(data.email_subject || '');
  if (!email.trim()) errors.push('email_body is empty');
  if (!wa.trim()) errors.push('whatsapp_body is empty');
  if (wa.length > 4000) errors.push('whatsapp_body exceeds WhatsApp limit');
  const allowed = new Set(numericTokens(JSON.stringify(model)));
  for (const o of model.options) {
    for (const [label, value] of [['fare', o.fare_label], ['baggage', o.baggage], ['change penalty', o.change_penalty], ['refund penalty', o.refund_penalty], ['airline', o.airline]]) {
      if (value && !email.includes(value)) errors.push(`email: option ${o.no} ${label} "${value}" missing or altered`);
    }
    if (!email.includes(o.departure_date_label)) errors.push(`email: option ${o.no} departure date missing or altered`);
    if (o.return_date_label && !email.includes(o.return_date_label)) errors.push(`email: option ${o.no} return date missing or altered`);
    if (!wa.includes(o.fare_amount_label)) errors.push(`whatsapp: option ${o.no} fare "${o.fare_amount_label}" missing or altered`);
    if (!wa.includes(o.airline)) errors.push(`whatsapp: option ${o.no} airline missing`);
  }
  for (const [name, text] of [['email', email], ['whatsapp', wa], ['subject', subject]]) {
    const unknown = numericTokens(text).filter((t) => !allowed.has(t));
    if (unknown.length) errors.push(`${name}: numbers not present in fare data: ${Array.from(new Set(unknown)).slice(0, 5).join(', ')}`);
    if (FORBIDDEN.test(text)) errors.push(`${name}: contains a forbidden commitment phrase`);
    if (containsSecret(text)) errors.push(`${name}: contains a secret-like pattern`);
  }
  if (!/subject to (?:re)?confirmation|subject to availability/i.test(email)) errors.push('email: availability disclaimer missing');
  if (!/subject to (?:re)?confirmation|subject to availability/i.test(wa)) errors.push('whatsapp: availability disclaimer missing');
  if (!subject.includes(model.rfq_number)) errors.push('subject: RFQ reference missing');
  return { ok: errors.length === 0, errors };
}

/** Validation of a human-edited quote: same checks, reported as warnings. */
function reviewEditedQuote(edited, model) {
  const result = validateFormattedQuote(edited, model);
  return { warnings: result.errors, clean: result.ok };
}

function optionsSummary(model) {
  return listJoin(model.options.map((o) => `Option ${o.no} ${o.airline} ${o.fare_amount_label}`));
}

module.exports = {
  QUOTE_SCHEMA,
  DISCLAIMER,
  buildQuoteModel,
  renderEmail,
  renderWhatsApp,
  buildFormatterUserContent,
  validateFormattedQuote,
  reviewEditedQuote,
  numericTokens,
  optionsSummary,
  formatInZone,
};

  },
  "lib/openai": function (module, exports, require) {
/**
 * OpenAI Chat Completions helpers (Structured Outputs / JSON Schema).
 * The HTTP call itself is done by an n8n HTTP Request node that uses the
 * "OpenAI (Offshore Fares)" credential – no key ever appears in code.
 */
const { supportsTemperature } = require('./config');
const { containsSecret } = require('./security');

function buildChatRequest({ model, system, user, schema, schemaName, temperature, maxTokens }) {
  const body = {
    model,
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: user },
    ],
    response_format: {
      type: 'json_schema',
      json_schema: { name: schemaName || 'result', strict: true, schema },
    },
  };
  if (supportsTemperature(model)) body.temperature = typeof temperature === 'number' ? temperature : 0;
  if (maxTokens) body.max_completion_tokens = maxTokens;
  return body;
}

/**
 * Parse an HTTP Request node output (success or `{ error }` when the node is set
 * to continue on fail). Returns { ok, data, error, usage, model }.
 */
function parseChatResponse(item) {
  const json = item || {};
  if (json.error) {
    const err = json.error;
    const message = typeof err === 'string' ? err : err.message || err.description || 'OpenAI request failed';
    return { ok: false, data: null, error: `OPENAI_HTTP_ERROR: ${String(message).slice(0, 300)}` };
  }
  const choice = json.choices && json.choices[0];
  if (!choice || !choice.message) return { ok: false, data: null, error: 'OPENAI_EMPTY_RESPONSE' };
  if (choice.message.refusal) return { ok: false, data: null, error: `OPENAI_REFUSAL: ${String(choice.message.refusal).slice(0, 200)}` };
  if (choice.finish_reason === 'length') return { ok: false, data: null, error: 'OPENAI_TRUNCATED' };
  const content = choice.message.content;
  let data;
  try {
    data = typeof content === 'string' ? JSON.parse(content) : content;
  } catch (e) {
    return { ok: false, data: null, error: 'OPENAI_INVALID_JSON' };
  }
  if (!data || typeof data !== 'object') return { ok: false, data: null, error: 'OPENAI_INVALID_JSON' };
  if (containsSecret(JSON.stringify(data))) return { ok: false, data: null, error: 'OPENAI_OUTPUT_CONTAINS_SECRET_PATTERN' };
  return { ok: true, data, error: null, usage: json.usage || null, model: json.model || null };
}

/** Helpers to declare strict JSON-schema fields compactly. */
const S = {
  str: () => ({ type: 'string' }),
  nstr: () => ({ type: ['string', 'null'] }),
  int: () => ({ type: 'integer' }),
  nint: () => ({ type: ['integer', 'null'] }),
  num: () => ({ type: 'number' }),
  nnum: () => ({ type: ['number', 'null'] }),
  bool: () => ({ type: 'boolean' }),
  nbool: () => ({ type: ['boolean', 'null'] }),
  enumOf: (values, nullable) => (nullable ? { type: ['string', 'null'], enum: values.concat([null]) } : { type: 'string', enum: values }),
  arr: (items) => ({ type: 'array', items }),
  obj: (properties, nullable) => ({
    type: nullable ? ['object', 'null'] : 'object',
    properties,
    required: Object.keys(properties),
    additionalProperties: false,
  }),
};

module.exports = { buildChatRequest, parseChatResponse, S };

  },
  "lib/config": function (module, exports, require) {
'use strict';
/**
 * Typed runtime configuration.
 *
 * In n8n Code nodes this is called with `$env`; in tests with a plain object.
 * Only NON-SECRET settings are read here. Secrets (OpenAI key, WhatsApp token,
 * database password) live in n8n Credentials and are never visible to Code nodes.
 */

const DEFAULTS = {
  DEMO_MODE: true,
  REQUIRE_HUMAN_APPROVAL: true,
  AUTO_ACKNOWLEDGE: true,
  COMPANY_NAME: 'Offshore Fares',
  COMPANY_SIGNATURE: 'Offshore Fares – Premium Fares Desk',
  BUSINESS_TIMEZONE: 'UTC',
  AI_PROVIDER: 'openai', // 'openai' | 'rules' (offline demo – deterministic fallback only)
  OPENAI_MODEL: 'gpt-4.1-mini',
  OPENAI_TEMPERATURE: 0,
  OPENAI_FORMATTER_TEMPERATURE: 0.2,
  AI_CONFIDENCE_THRESHOLD: 0.7,
  CORRELATION_WINDOW_HOURS: 72,
  CLARIFICATION_DEBOUNCE_SECONDS_WHATSAPP: 45,
  CLARIFICATION_DEBOUNCE_SECONDS_EMAIL: 0,
  MAX_CLARIFICATIONS: 2,
  GROUP_MIN_PASSENGERS: 10,
  FOLLOWUP_1_HOURS: 4,
  FOLLOWUP_2_HOURS: 24,
  MAX_FOLLOWUPS: 2,
  SLA_NEW_MINUTES: 5,
  SLA_READY_FOR_SEARCH_MINUTES: 10,
  SLA_ASSIGNED_MINUTES: 15,
  SLA_SEARCHING_MINUTES: 45,
  SLA_FARES_FOUND_MINUTES: 10,
  SLA_PENDING_APPROVAL_MINUTES: 10,
  SLA_BOOKING_REQUEST_MINUTES: 5,
  SLA_CHANGE_REQUEST_MINUTES: 15,
  SLA_REFUND_REQUEST_MINUTES: 60,
  SLA_CRITICAL_FACTOR: 0.5,
  WHATSAPP_GRAPH_VERSION: 'v21.0',
  WHATSAPP_PHONE_NUMBER_ID: '',
  WHATSAPP_FOLLOWUP_TEMPLATE: 'quote_followup',
  WHATSAPP_TEMPLATE_LANGUAGE: 'en',
  WHATSAPP_SIGNATURE_REQUIRED: false,
  DATE_ORDER: 'DMY',
  PRIORITY_RULES_JSON: '',
};

const BOOLEAN_KEYS = ['DEMO_MODE', 'REQUIRE_HUMAN_APPROVAL', 'AUTO_ACKNOWLEDGE', 'WHATSAPP_SIGNATURE_REQUIRED'];

function readEnv(env, key) {
  try {
    const value = env ? env[key] : undefined;
    return value === undefined || value === null || value === '' ? undefined : value;
  } catch (_) {
    // n8n throws when env access is blocked; fall back to defaults.
    return undefined;
  }
}

function toBool(value, fallback) {
  if (value === undefined) return fallback;
  if (typeof value === 'boolean') return value;
  return ['1', 'true', 'yes', 'on'].includes(String(value).trim().toLowerCase());
}

function getConfig(env) {
  const cfg = {};
  for (const key of Object.keys(DEFAULTS)) {
    const fallback = DEFAULTS[key];
    const raw = readEnv(env, key);
    if (BOOLEAN_KEYS.includes(key)) cfg[key] = toBool(raw, fallback);
    else if (typeof fallback === 'number') {
      const n = raw === undefined ? NaN : Number(raw);
      cfg[key] = Number.isFinite(n) ? n : fallback;
    } else cfg[key] = raw === undefined ? fallback : String(raw);
  }
  return cfg;
}

/** Reasoning-family models reject custom temperature; everything else gets a low one. */
function supportsTemperature(model) {
  return !/^(o\d|gpt-5)/i.test(String(model || ''));
}

module.exports = { DEFAULTS, getConfig, supportsTemperature, toBool };

  },
  "lib/security": function (module, exports, require) {
/**
 * Prompt-injection screening and secret redaction.
 *
 * Defence in depth – the real protections are architectural:
 *  - the model never receives secrets (keys live in n8n Credentials),
 *  - the model only returns schema-constrained JSON that code validates,
 *  - the model cannot trigger sends: delivery is decided by workflow logic + human approval.
 * This module adds detection (flag + audit + human review) and output scrubbing.
 */

const INJECTION_PATTERNS = [
  { id: 'ignore_instructions', re: /\b(ignore|disregard|forget|override)\b[^.\n]{0,40}\b(instructions?|prompts?|rules?|guidelines?)\b/i },
  { id: 'reveal_secret', re: /\b(show|reveal|print|give|send|tell|display|leak|share|output)\b[^.\n]{0,40}\b(api[\s_-]?keys?|secrets?|passwords?|tokens?|credentials?|system prompt|env(?:ironment)? variables?)\b/i },
  { id: 'role_override', re: /\b(you are now|act as|pretend to be|from now on you|developer mode|jailbreak|DAN mode)\b/i },
